const pickLang = (row: string, lang: string) => {
  const parts = row.split('|');
  const i = COACH_LANGS.indexOf(lang as (typeof COACH_LANGS)[number]);
  return parts[i >= 0 ? i : 0] || parts[0];
};

/** Translated coach label. Unknown keys return the key itself so gaps are visible, never silent. */
export function coachText(key: string, lang?: string, ...args: unknown[]): string {
  const row = D[key];
  if (!row) return key;
  const s = pickLang(row, lang ?? txLang());
  return args.length ? s.replace(/\{(\d+)\}/g, (m, i) => (args[+i] !== undefined ? String(args[+i]) : m)) : s;
}

/** Stage-specific reading / six questions (field order) / support / output instructions. */
export function stageCoach(stage: string, lang?: string): { reading: string; questions: string[]; help: string; deliverable: string } {
  const g = S[stage === 'middle' || stage === 'high' ? stage : 'other'];
  const l = lang ?? txLang();
  return { reading: pickLang(g.reading, l), help: pickLang(g.help, l), deliverable: pickLang(g.deliverable, l), questions: [0, 1, 2, 3, 4, 5].map((i) => pickLang(g[`q${i}`], l)) };
}

export const coachKeys = () => Object.keys(D);
